-- Converted from SQLite dump_utf8.sql to PostgreSQL
BEGIN;

-- users
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  password TEXT NOT NULL
);


-- tabs
CREATE TABLE IF NOT EXISTS tabs (
  id SERIAL PRIMARY KEY,
  name TEXT,
  user_id INTEGER REFERENCES users(id)
);


-- blocks
CREATE TABLE IF NOT EXISTS blocks (
  id SERIAL PRIMARY KEY,
  tab_id INTEGER REFERENCES tabs(id),
  user_id INTEGER REFERENCES users(id),
  day_name TEXT,
  breakfast TEXT,
  lunch TEXT,
  dinner TEXT
);


-- chats
CREATE TABLE IF NOT EXISTS chats (
  id SERIAL PRIMARY KEY,
  thread_id INTEGER REFERENCES threads(id),
  user_id INTEGER REFERENCES users(id),
  content TEXT,
  role TEXT NOT NULL DEFAULT 'user',
  image_path TEXT
);


-- threads
CREATE TABLE IF NOT EXISTS threads (
  id SERIAL PRIMARY KEY,
  user_id INTEGER REFERENCES users(id),
  name TEXT
);


-- meal_tracking
CREATE TABLE IF NOT EXISTS meal_tracking (
  id SERIAL PRIMARY KEY,
  user_id INTEGER REFERENCES users(id),
  date DATE NOT NULL,
  breakfast_done BOOLEAN DEFAULT FALSE,
  lunch_done BOOLEAN DEFAULT FALSE,
  dinner_done BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP DEFAULT now(),
  UNIQUE(user_id, date)
);

-- user_settings
CREATE TABLE IF NOT EXISTS user_settings (
  id SERIAL PRIMARY KEY,
  user_id INTEGER UNIQUE REFERENCES users(id),
  main_tab_id INTEGER REFERENCES tabs(id)
);


-- set sequences to match previous max ids
SELECT setval(pg_get_serial_sequence('users','id'), 6, true);
SELECT setval(pg_get_serial_sequence('tabs','id'), 3, true);
SELECT setval(pg_get_serial_sequence('blocks','id'), 8, true);
SELECT setval(pg_get_serial_sequence('threads','id'), 27, true);
SELECT setval(pg_get_serial_sequence('chats','id'), 73, true);
SELECT setval(pg_get_serial_sequence('user_settings','id'), 1, true);

COMMIT;
